def solve(inputs: dict) -> float:
    remainders = inputs['remainders']
    moduli = inputs['moduli']

    # Chinese Remainder Theorem
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    # CRT algorithm
    result = 0
    total_mod = 1
    for m in moduli:
        total_mod *= m

    for r, m in zip(remainders, moduli):
        M_i = total_mod // m
        y_i = mod_inverse(M_i, m)
        result += r * M_i * y_i

    result = result % total_mod
    return float(result)
