    X = inputs['X']
    steps = inputs['steps']

    # 32-bit mask
    MASK_32 = (1 << 32) - 1

    for _ in range(steps):
        X ^= (X << 13) & MASK_32
        X ^= (X >> 7) & MASK_32
        X ^= (X << 15) & MASK_32
        X &= MASK_32

